/**
 * The read-only rule for workspaces whose subscription is not in good standing.
 *
 * `lockReasonFor` is the pure rule over a stored subscription. The write paths
 * never call it directly: they go through `assertWorkspaceWritable()` in
 * billing-service, which loads the subscription and throws
 * `WorkspaceLockedError` when the rule says the workspace is locked.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

/** A write was refused because the workspace is read-only. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace is read-only (${reason}); update billing to restore writes`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable. A
 * missing subscription is writable: only a stored row can put a workspace into
 * a state that blocks writes.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      // A cancellation with no date has no future to wait for.
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
  }
}

/** The boundary instant counts as reached: the lock applies at, not after, it. */
function hasReached(instant: IsoTimestamp, now: Date): boolean {
  return now.getTime() >= new Date(instant).getTime();
}

