 * Why the workspace is locked at `now`, or `null` when it is writable. A
 * missing subscription is writable: only a stored row can put a workspace into
 * a state that blocks writes.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now)
        ? "trial_ended"
        : null;
    case "canceled":
      // A cancellation with no date has no future to wait for.
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
  }
}

/** The boundary instant counts as reached: the lock applies at, not after, it. */
function hasReached(instant: IsoTimestamp, now: Date): boolean {
  return now.getTime() >= new Date(instant).getTime();
}

