/** The pure read-only rule over a stored subscription, and the error it raises. */
import { describe, expect, it } from "vitest";
import { lockReasonFor, WorkspaceLockedError } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, SubscriptionId } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const PERIOD_END = "2026-06-01T00:00:00.000Z";
const BEFORE = new Date("2026-05-31T23:59:59.999Z");
const AT = new Date(PERIOD_END);
const LATER = new Date("2026-12-01T00:00:00.000Z");

function subscription(overrides: Partial<Subscription> = {}): Subscription {
  const stamp = "2026-05-01T00:00:00.000Z" as IsoTimestamp;
  return {
    id: "01HZZZSSSSSSSSSSSSSSSSSSS1" as SubscriptionId,
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 4,
    currentPeriodStart: stamp,
    currentPeriodEnd: PERIOD_END as IsoTimestamp,
    cancelAt: null,
    createdAt: stamp,
    updatedAt: stamp,
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  it("leaves a workspace with no subscription row writable", () => {
    expect(lockReasonFor(null, LATER)).toBeNull();
  });

  it("leaves an active subscription writable, even past its period end", () => {
    expect(lockReasonFor(subscription({ status: "active" }), LATER)).toBeNull();
  });

  it("locks a past-due subscription straight away", () => {
    expect(
      lockReasonFor(subscription({ status: "past_due" }), BEFORE),
    ).toBe("past_due");
  });

  it("locks a trial from the moment its period end is reached", () => {
    const trialing = subscription({ status: "trialing" });

    expect(lockReasonFor(trialing, BEFORE)).toBeNull();
    expect(lockReasonFor(trialing, AT)).toBe("trial_ended");
    expect(lockReasonFor(trialing, LATER)).toBe("trial_ended");
  });

  it("keeps a scheduled cancellation writable until its date arrives", () => {
    const canceled = subscription({
      status: "canceled",
      cancelAt: "2026-06-15T00:00:00.000Z" as IsoTimestamp,
    });

    expect(lockReasonFor(canceled, new Date("2026-06-14T23:59:59.999Z"))).toBeNull();
    expect(lockReasonFor(canceled, new Date("2026-06-15T00:00:00.000Z"))).toBe(
      "canceled",
    );
  });

  it("treats a canceled subscription with no cancellation date as canceled now", () => {
    expect(
      lockReasonFor(subscription({ status: "canceled", cancelAt: null }), BEFORE),
    ).toBe("canceled");
  });
});

describe("WorkspaceLockedError", () => {
  it("is a domain error mapped to plan_limit_exceeded with the reason in meta", () => {
    const error = new WorkspaceLockedError(ORG_A, "trial_ended");

    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({
      code: "plan_limit_exceeded",
      meta: { reason: "trial_ended" },
    });
  });
});

