/**
 * A workspace that is not in good standing is read-only: writes are refused
 * once their permission check has passed, while reads and billing stay open.
 */
import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { WorkspaceLockedError } from "@/lib/billing-lock";
import { PermissionDeniedError } from "@/lib/permissions";
import { getDb, subscriptions } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as billingService from "@/server/services/billing-service";
import * as issueService from "@/server/services/issue-service";
import * as organizationService from "@/server/services/organization-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { SubscriptionStatus } from "@/types/billing";
import type { OrgId } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** The lock is a function of the stored row, so the test writes that row directly. */
function storeSubscription(
  orgId: OrgId,
  status: SubscriptionStatus,
  cancelAt: string | null = null,
): void {
  getDb()
    .update(subscriptions)
    .set({ status, cancelAt })
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("services/billing-lock", () => {
  it("refuses a member's issue write and stores nothing, while reads still work", async () => {
    const tenant = await createTenant("lock-write", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Written before the lock" }),
    );
    storeSubscription(tenant.org.id, "past_due");

    const refused = issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Refused" }),
    );
    await expect(refused).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(refused).rejects.toMatchObject({ reason: "past_due" });

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });
    expect(page.items.map((row) => row.id)).toEqual([issue.id]);

    await expect(
      issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).resolves.toMatchObject({ issue: { id: issue.id } });
  });

  it("keeps the permission refusal a caller would get in an unlocked workspace", async () => {
    const tenant = await createTenant("lock-permission", "growth");
    storeSubscription(tenant.org.id, "past_due");

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("keeps billing open, and a successful plan change makes the workspace writable", async () => {
    const tenant = await createTenant("lock-billing", "growth");
    storeSubscription(tenant.org.id, "past_due");

    await expect(
      billingService.getBillingSummary(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "past_due" });
    await expect(
      organizationService.getOrganizationSummary(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "past_due" });

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
  });

  it("locks an ended trial, and the move to the free plan unlocks it", async () => {
    const tenant = await createTenant("lock-trial", "growth");
    const afterTrial = new Date(Date.now() + 15 * DAY_MS);

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, afterTrial),
    ).rejects.toMatchObject({ reason: "trial_ended" });

    await subscriptionRepo.updateSubscriptionPlan(tenant.org.id, "free", "monthly");

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, afterTrial),
    ).resolves.toBeUndefined();
  });

  it("applies a cancellation on its date, not before", async () => {
    const tenant = await createTenant("lock-cancel", "growth");

    storeSubscription(tenant.org.id, "canceled", "2099-01-01T00:00:00.000Z");
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();

    storeSubscription(tenant.org.id, "canceled", "2020-01-01T00:00:00.000Z");
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).rejects.toMatchObject({ reason: "canceled" });
  });
});

